import type { ChatMemoryMessage } from './chat';
import { noTextReason } from './llm-call';

/** 当前模型与可选推理等级。 */
export interface VoiceModel {
  provider: string;
  model: string;
  reasoningEffort?: string;
}
/** 只依赖可取消的模型流。 */
export interface VoiceLlm {
  stream(options: unknown): AsyncIterable<StreamChunk>;
}
/** 正文流；API 错误不会被当作空回答。 */
export async function* streamVoiceReply(
  llm: VoiceLlm,
  model: VoiceModel,
  system: string,
  history: ChatMemoryMessage[],
  text: string,
  signal: AbortSignal,
): AsyncGenerator<string> {
  signal.throwIfAborted();
