    ...history.map((m) =>
      m.role === 'user'
        ? createUserMessage({ content: [{ type: 'text', text: m.content }], source: { kind: 'user' } })
        : createAssistantMessage({
            content: [{ type: 'text', text: m.content }],
            source: { provider: model.provider, model: model.model },
          }),
    ),
    createUserMessage({ content: [{ type: 'text', text }], source: { kind: 'user' } }),
  ];
  for await (const chunk of llm.stream({ ...model, system, messages, sessionId: 'dsh-pet', signal })) {
    signal.throwIfAborted();
    if (chunk.type === 'text-delta' && chunk.text) yield chunk.text;
    if (chunk.type === 'finish' && (chunk.reason.kind === 'error' || chunk.reason.kind === 'aborted'))
      throw new Error(noTextReason(chunk.reason));
  }
}

/** @module dsh-pet/src/host/voice-stream.test */
import test from 'node:test';
import assert from 'node:assert/strict';
import { streamVoiceReply } from './voice-stream';
test('voice uses explicit DSH model, only emits text and propagates cancellation', async () => {
  const control = new AbortController();
  let selected: unknown;
  const llm = {
    async *stream(options: unknown) {
      selected = options;
      yield { type: 'reasoning-delta' as const, index: 0, text: 'hidden' };
      yield { type: 'text-delta' as const, index: 1, text: '你好' };
      control.abort();
      yield { type: 'text-delta' as const, index: 1, text: 'late' };
    },
  };
  const values: string[] = [];
  await assert.rejects(async () => {
    for await (const text of streamVoiceReply(
      llm,
      { provider: 'test', model: 'same-as-dsh' },
      'persona',
      [],
      'hello',
      control.signal,
    ))
      values.push(text);
  });
  assert.deepEqual(values, ['你好']);
  assert.equal((selected as { model: string }).model, 'same-as-dsh');
});

