const PANEL_ID = 'dsh-pet-voice-panel';
const MARGIN = 8;
const MIN_WIDTH = 320;
const MIN_HEIGHT = 400;
const DEFAULT_WIDTH = 392;
const DEFAULT_HEIGHT = 580;
const KEY_STEP = 16;
const EDGES = ['n', 's', 'e', 'w', 'ne', 'nw', 'se', 'sw'] as const;
type Edge = (typeof EDGES)[number];
type Theme = 'light' | 'dark';

/** 浮窗在视口中的位置和大小（CSS 像素）。 */
interface Geometry {
  x: number;
  y: number;
  width: number;
  height: number;
}

const KEY_MOVES: Record<string, [number, number]> = {
  ArrowLeft: [-1, 0],
  ArrowRight: [1, 0],
  ArrowUp: [0, -1],
  ArrowDown: [0, 1],
};

