const ICON_GRIP =
  '<svg class="vp-grip" viewBox="0 0 8 14" aria-hidden="true"><g fill="currentColor"><circle cx="2" cy="2" r="1.2"/><circle cx="6" cy="2" r="1.2"/><circle cx="2" cy="7" r="1.2"/><circle cx="6" cy="7" r="1.2"/><circle cx="2" cy="12" r="1.2"/><circle cx="6" cy="12" r="1.2"/></g></svg>';
const ICON_RESET =
  '<svg viewBox="0 0 16 16" aria-hidden="true"><path fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" d="M3 8a5 5 0 1 0 1.5-3.6M3 2.5v2.4h2.4"/></svg>';
const ICON_CLOSE =
  '<svg viewBox="0 0 16 16" aria-hidden="true"><path fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" d="M4 4l8 8M12 4l-8 8"/></svg>';

let stylesInstalled = false;

/** 安装一次浮窗样式；不支持可构造样式表时退回 style 元素。 */
function installStyles(): void {
  if (stylesInstalled) return;
  stylesInstalled = true;
  try {
    const sheet = new CSSStyleSheet();
    sheet.replaceSync(PANEL_CSS);
    document.adoptedStyleSheets = [...document.adoptedStyleSheets, sheet];
  } catch {
    const style = document.createElement('style');
    style.textContent = PANEL_CSS;
    document.head.append(style);
  }
}

/** DSH 深色主题或深色页面底色优先，其次跟随系统。 */
function resolveTheme(): Theme {
  if (document.body.hasAttribute('data-ds-dark-theme')) return 'dark';
  const match = /rgba?\(([\d.]+),\s*([\d.]+),\s*([\d.]+)(?:,\s*([\d.]+))?\)/.exec(
    getComputedStyle(document.body).backgroundColor,
  );
  if (match && (match[4] === undefined || Number(match[4]) > 0.5)) {
    const luminance = (0.2126 * Number(match[1]) + 0.7152 * Number(match[2]) + 0.0722 * Number(match[3])) / 255;
    return luminance < 0.45 ? 'dark' : 'light';
  }
  return matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

function storageKey(petId: string): string {
  return 'dsh-pet-voice-panel:' + petId;
}

function isGeometry(value: unknown): value is Geometry {
  if (!value || typeof value !== 'object') return false;
  const record = value as Record<string, unknown>;
  return ['x', 'y', 'width', 'height'].every(key => {
    const n = record[key];
    return typeof n === 'number' && Number.isFinite(n);
  });
}

/** 读取上次的位置；存储不可用或内容无效时返回 undefined。 */
function loadGeometry(petId: string): Geometry | undefined {
  try {
    const raw = localStorage.getItem(storageKey(petId));
    const value: unknown = raw ? JSON.parse(raw) : undefined;
    return isGeometry(value) ? value : undefined;
  } catch {
    return undefined;
  }
}

function saveGeometry(petId: string, geometry: Geometry): void {
  try {
    localStorage.setItem(storageKey(petId), JSON.stringify(geometry));
  } catch {
    // 存储不可用时只是不记位置。
  }
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), Math.max(min, max));
}

/** 视口放不下最小尺寸时，最小尺寸让位于视口。 */
function minimumSize(): { width: number; height: number } {
  return {
    width: Math.min(MIN_WIDTH, window.innerWidth - 2 * MARGIN),
    height: Math.min(MIN_HEIGHT, window.innerHeight - 2 * MARGIN),
  };
}

function defaultGeometry(): Geometry {
  const width = Math.min(DEFAULT_WIDTH, window.innerWidth - 2 * MARGIN);
  const height = Math.min(DEFAULT_HEIGHT, window.innerHeight - 2 * MARGIN);
  return { x: window.innerWidth - MARGIN - width, y: MARGIN, width, height };
}

/** 把浮窗完整收进视口。 */
function fit(geometry: Geometry): Geometry {
  const min = minimumSize();
  const width = clamp(geometry.width, min.width, window.innerWidth - 2 * MARGIN);
  const height = clamp(geometry.height, min.height, window.innerHeight - 2 * MARGIN);
  return {
    x: clamp(geometry.x, MARGIN, window.innerWidth - MARGIN - width),
    y: clamp(geometry.y, MARGIN, window.innerHeight - MARGIN - height),
    width,
    height,
  };
}

/** 从某条边或角落调整大小，对边保持不动。 */
function resize(start: Geometry, edge: Edge, dx: number, dy: number): Geometry {
  const min = minimumSize();
  let left = start.x;
  let top = start.y;
  let right = start.x + start.width;
  let bottom = start.y + start.height;
  if (edge.includes('w')) left = Math.min(Math.max(MARGIN, left + dx), right - min.width);
  if (edge.includes('e')) right = Math.max(Math.min(window.innerWidth - MARGIN, right + dx), left + min.width);
  if (edge.includes('n')) top = Math.min(Math.max(MARGIN, top + dy), bottom - min.height);
  if (edge.includes('s')) bottom = Math.max(Math.min(window.innerHeight - MARGIN, bottom + dy), top + min.height);
  return { x: left, y: top, width: right - left, height: bottom - top };
}

function place(root: HTMLElement, geometry: Geometry): void {
  root.style.left = geometry.x + 'px';
  root.style.top = geometry.y + 'px';
  root.style.width = geometry.width + 'px';
  root.style.height = geometry.height + 'px';
}

function iconButton(label: string, icon: string): HTMLButtonElement {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'vp-btn';
  button.title = label;
  button.setAttribute('aria-label', label);
  button.innerHTML = icon;
  return button;
}

/**
 * 打开（或重新打开）某只 Pet 的语音浮窗。
 * @param petId - 当前 Pet。
 * @param base - 现有桌宠桥地址。
 */
export async function mountVoicePanel(petId: string, base: string): Promise<void> {
  document.getElementById(PANEL_ID)?.remove();
  const response = await fetch(base + '/voice-panel?pet=' + encodeURIComponent(petId), { method: 'POST' });
  const result: unknown = await response.json();
  if (!result || typeof result !== 'object' || !('url' in result) || typeof result.url !== 'string')
    throw new Error('统一语音插件尚未就绪');
  const url = new URL(result.url);
  if (url.protocol !== 'http:' || url.hostname !== '127.0.0.1') throw new Error('语音地址必须来自本机');
  const theme = resolveTheme();
  url.searchParams.set('theme', theme);
  installStyles();
  // 连续点击时，等待期间可能已经打开过一个。
  document.getElementById(PANEL_ID)?.remove();

  const root = document.createElement('div');
  root.id = PANEL_ID;
  root.dataset.petId = petId;
  root.dataset.theme = theme;
  root.setAttribute('role', 'dialog');
  root.setAttribute('aria-label', 'Pet 语音');

  const head = document.createElement('div');
  head.className = 'vp-head';
  head.tabIndex = 0;
  head.title = '拖动移动；方向键移动，Shift+方向键调整大小；双击复位';
  head.setAttribute('aria-label', '移动语音面板：方向键移动，Shift+方向键调整大小，双击或按 Home 复位');
  head.innerHTML = ICON_GRIP;
  const title = document.createElement('p');
  title.className = 'vp-title';
  title.textContent = 'Pet 语音';
  const reset = iconButton('复位大小和位置', ICON_RESET);
  const close = iconButton('关闭语音面板', ICON_CLOSE);
  head.append(title, reset, close);

  const frame = document.createElement('iframe');
  frame.className = 'vp-frame';
  frame.src = url.href;
  frame.allow = 'microphone; autoplay';
  frame.title = 'Pet 语音';

  let geometry = fit(loadGeometry(petId) ?? defaultGeometry());
  const update = (next: Geometry, persist: boolean): void => {
    geometry = next;
    place(root, geometry);
    if (persist) saveGeometry(petId, geometry);
  };
  const onResize = (): void => {
    if (!root.isConnected) {
      window.removeEventListener('resize', onResize);
      return;
    }
    update(fit(geometry), false);
  };
  const dismiss = (): void => {
    window.removeEventListener('resize', onResize);
    root.remove();
  };
  const restore = (): void => update(defaultGeometry(), true);

  // 拖动期间 iframe 不接收指针，指针一直归按下的元素。
  const gesture = (event: PointerEvent, edge: Edge | 'move'): void => {
    if (event.button !== 0) return;
    const handle = event.currentTarget;
    if (!(handle instanceof HTMLElement)) return;
    event.preventDefault();
    const start = geometry;
    const startX = event.clientX;
    const startY = event.clientY;
    handle.setPointerCapture(event.pointerId);
    root.dataset.gesture = edge;
    const move = (next: PointerEvent): void => {
      const dx = next.clientX - startX;
      const dy = next.clientY - startY;
      update(edge === 'move' ? fit({ ...start, x: start.x + dx, y: start.y + dy }) : resize(start, edge, dx, dy), false);
    };
    const end = (): void => {
      handle.removeEventListener('pointermove', move);
      handle.removeEventListener('pointerup', end);
      handle.removeEventListener('pointercancel', end);
      delete root.dataset.gesture;
      saveGeometry(petId, geometry);
    };
    handle.addEventListener('pointermove', move);
    handle.addEventListener('pointerup', end);
    handle.addEventListener('pointercancel', end);
  };

  head.addEventListener('pointerdown', event => {
    if (event.target instanceof Element && event.target.closest('.vp-btn')) return;
    gesture(event, 'move');
  });
  head.addEventListener('dblclick', event => {
    if (event.target instanceof Element && event.target.closest('.vp-btn')) return;
    restore();
  });
  head.addEventListener('keydown', event => {
    if (event.target !== head) return;
    if (event.key === 'Home') {
      event.preventDefault();
      restore();
      return;
    }
    const step = KEY_MOVES[event.key];
    if (!step) return;
    event.preventDefault();
    const [dx, dy] = step;
    update(
      event.shiftKey
        ? resize(geometry, 'se', dx * KEY_STEP, dy * KEY_STEP)
        : fit({ ...geometry, x: geometry.x + dx * KEY_STEP, y: geometry.y + dy * KEY_STEP }),
      true,
    );
  });
  root.addEventListener('keydown', event => {
    if (event.key === 'Escape') dismiss();
  });
  reset.addEventListener('click', restore);
  close.addEventListener('click', dismiss);

  const handles = EDGES.map(edge => {
    const handle = document.createElement('div');
    handle.className = 'vp-edge vp-' + edge;
    handle.setAttribute('aria-hidden', 'true');
    handle.addEventListener('pointerdown', event => gesture(event, edge));
    return handle;
  });

  root.append(head, frame, ...handles);
  place(root, geometry);
  document.body.append(root);
  window.addEventListener('resize', onResize);
}

/**
 * 现有 Pet 的无麦克风后台播放器。面板打开时让出声音，卸载时释放 iframe。
 * @param petId - 当前 Pet。
 * @param base - 现有桌宠桥地址。
 * @returns 卸载清理函数。
 */
export function mountVoiceAgent(petId: string, base: string): () => void {
  let disposed = false;
  let frame: HTMLIFrameElement | undefined;
  let timer: ReturnType<typeof setTimeout>;
  const mount = async (): Promise<void> => {
    try {
      const response = await fetch(base + '/voice-panel?pet=' + encodeURIComponent(petId), { method: 'POST' });
      const value: unknown = await response.json();
      if (disposed) return;
      if (!response.ok || !value || typeof value !== 'object' || !('url' in value) || typeof value.url !== 'string')
        throw new Error('voice unavailable');
      const url = new URL(value.url);
      if (url.protocol !== 'http:' || url.hostname !== '127.0.0.1') throw new Error('invalid voice origin');
      url.searchParams.set('background', '1');
      frame?.remove();
      frame = document.createElement('iframe');
      frame.hidden = true;
      frame.allow = 'autoplay';
      frame.title = 'Pet 后台语音（不启用麦克风）';
      frame.src = url.href;
      document.body.append(frame);
      timer = setTimeout(() => {
        void mount();
      }, 30 * 60000);
    } catch {
      if (!disposed)
        timer = setTimeout(() => {
          void mount();
        }, 30000);
    }
  };
  void mount();
  return () => {
    disposed = true;
    clearTimeout(timer);
    frame?.remove();
  };
}
